; =============================================================================
;  FLYING SAUCERS  -  TRS-80 Model I, Level II, 4K
;  Radio Shack catalog number 26-1905. Program (c) 1979 Robert Arnstein,
;  licensed to Tandy Corporation (manual, (c) 1979, 1981 Tandy Corporation).
; -----------------------------------------------------------------------------
;  Commented disassembly of flysauc5.cmd, a disk (/CMD) wrapping of the
;  SYSTEM tape. Generated by tools/listing.py from the file and
;  tools/annot.py; this file is the source of truth (see RIGHTS.md).
;
;  Rebuild:   pasmo --bin flysaucers.asm flysaucers.bin
;             python3 tools/mkcmd.py flysaucers.bin FLYSAUC5.CMD
;  The result is byte-identical to flysauc5.cmd (SHA-256 0f27a03a...44d38).
;
;  How the file loads
;    The /CMD file loads 5300h-603Eh and starts at 5300h. The 27-byte stub
;    there copies 36h bytes of the ROM's start-up table (06D2h) to 4000h,
;    the way the ROM does at power-on, then moves the game from 531Bh down to
;    42EAh, where the SYSTEM tape would have put it, and jumps there. The game
;    itself (42EAh-4FFAh) is the same, byte for byte, in three of the five
;    copies in the archive (flysauc2, 3 and 5).
;
;  Memory map while the game runs (a 4K machine: RAM ends at 4FFFh)
;    3800-3BFF  keyboard matrix (read only through the ROM, see GET_KEY)
;    3C00-3FFF  video RAM, 64 x 16 characters; 80h-BFh are 2x3 graphics blocks
;    4000-42E9  ROM work area (the keyboard routine uses it)
;    42EA-4C47  program
;    4C48-4CD8  saucer table (15 x 5 bytes) and shot table (20 x 3 bytes)
;    4CD9-4FE6  variables, text, saucer and cannon pictures, tables
;    4FE7-4FF8  the stack (18 bytes; 16 is the most ever used)
;
;  The world is the screen. The program keeps a position for every saucer and
;  every shot, but never asks whether two of them meet: each mover looks at the
;  character already in video RAM where it is about to go. A shot that finds
;  anything there has hit it; a saucer that finds anything but a blank or a shot
;  there has crashed into it. And a shot has no direction of its own: every time
;  it moves, it moves the way the cannon points NOW (see MOVE_SHOTS). That is how
;  "the aiming keys can also change the direction of the missile after the
;  missile has left the cannon" (the manual).
;
;  The program never enables interrupts. There is no clock: one pass of the main
;  loop is the unit of time, padded by DELAY, and every speed in the game is a
;  count of passes.
;
;  Self-modifying code (all of it; the emulator's write watch on 42EAh-4C47h
;  finds no other writes):
;    4514h  operand of AND in UPDATE: FFh normally, 7Fh in the demonstration,
;           which doubles the chance of a new saucer on each pass
;    4BDCh, 4BE5h  PRINT_BCD switches both between LD A,L and LD A,H to walk
;           down the digits of HL
; =============================================================================

; ---- addresses outside the program ----
ROM_KBD          equ 002Bh	; Level II ROM: scan the keyboard; A = code of a key just pressed, 0 if none (uses DE)
ROM_INIT_TABLE   equ 06D2h	; Level II ROM: the table it copies to 4000h at power-on
VIDEO            equ 3C00h
ROM_RAM          equ 4000h	; ROM work area: restart vectors and device blocks

; ---- names for bytes inside the tables ----
SCORE_HI         equ SCORE+1	; hundreds and thousands digits of SCORE
NEW_LEAD         equ CUR_REC+2	; spawning a left-to-right saucer: its lead cell
NEW_RIGHT        equ CUR_REC+4	; spawning a right-to-left saucer: its right end (stored, never read)

	org 42EAh

;---------------------------------------------------------------
; START — power-on of the game, and where r and enter come back to. sets the stack,
;
; clears DEMO, puts AND 0FFh back into UPDATE (the demonstration changes it),
; then falls into TITLE.
; In:        nothing (SP is reset)
; Changes:   nothing
; Preserves: A, B, C (register), D, E, H, L, IX, IY; flags S Z H P/V N C
;            [static]
; Memory:    writes DEMO, LIGHTS_SMALL, SPAWN_MASK+1
; Stack:     0 bytes max, callees included  [static]
; Cycles:    not called in the scenarios
; Exit:      falls into TITLE
; Jumped to from: MAIN_LOOP (447Ah), DO_KEY (4502h), LOADER (5318h)
;---------------------------------------------------------------
START:
	ld sp,STACK_TOP	; the stack: 4FF9h down, at the top of a 4K machine
	sub a	; A = 0
	ld (LIGHTS_SMALL),a	; small saucers' lights: phase 0
	ld (DEMO),a	; not the demonstration
	ld a,0FFh	; put AND 0FFh back into SPAWN
	ld (SPAWN_MASK+1),a	; SELF-MODIFIES 4514h (the demonstration writes 7Fh)

;---------------------------------------------------------------
; TITLE — draws the whole screen: the frame (a bar of 83h along the top, the side
;
; walls 95h/AAh), the title, the instructions, the score labels. Clears both
; tables, zeroes SCORE, HITS and SHOTS, points the cannon straight up. In the
; demonstration it pauses and starts by itself; otherwise it waits for 1-9
; (start) or D (demonstration).
; The demonstration also comes back here when its time is up, without
; passing START, so it keeps running until a key stops it (R, or a digit
; to change its difficulty).
; Changes:   nothing
; Preserves: A, B, C (register), D, E, H, L, IX, IY; flags S Z H P/V N C
;            [static]
; Memory:    writes AIM, DEMO, EXTRA_LEFT, HIT_COUNT, LOADING, SAUCERS_END, SCORE, SHOT_COUNT, SPAWN_MASK+1, VIDEO, VIDEO+63; reads DEMO
; Stack:     18 bytes max, callees included  [static]
; Cycles:    not called in the scenarios
; Calls:     WAIT, DO_KEY, DRAW_CANNON, UPDATE, FLASH, SHOW_COUNTS, TICK_CLOCK, PRINT, PRINT_BCD, DELAY, GET_KEY, RANDOM
; Jumped to from: MAIN_LOOP (446Ch)
;---------------------------------------------------------------
TITLE:
	ld hl,VIDEO	; clear the screen
	ld de,0400h	; 1,024 cells
CLS_LOOP:
	ld (hl),20h	; blank
	inc hl
	dec de
	ld a,d
	or e
	jp nz,CLS_LOOP
	ld hl,VIDEO	; row 0: a bar of 83h (the top third of a block lit)
	ld c,40h	; 64 cells
TOP_BAR:
	ld (hl),83h
	inc hl
	dec c
	jp nz,TOP_BAR
	ld hl,VIDEO+64	; the side walls, rows 1-15
	ld de,003Fh	; from column 0 to column 63 of the same row
	ld c,0Fh	; 15 rows
SIDE_WALLS:
	ld (hl),95h	; left wall: 95h, the left column of a block
	add hl,de	; to column 63
	ld (hl),0AAh	; right wall: AAh, the right column
	inc hl	; to column 0 of the next row
	dec c
	jp nz,SIDE_WALLS
	ld a,97h	; the top corners
	ld (VIDEO),a
	ld a,0ABh
	ld (VIDEO+63),a
	ld hl,TXT_TITLE	; " RADIO SHACK -- FLYING SAUCERS "
	ld de,VIDEO+15	; centred on row 0
	call PRINT	; print the string
	ld de,VIDEO+132	; instructions from row 2, column 4
	ld hl,TXT_INSTRUCTIONS	; the instruction strings, one per row; an empty one is a blank line
INSTR_LOOP:
	ld a,(hl)	; a 0 where a string should start ends the list
	and a
	jp z,CLEAR_TABLES
	push de	; keep the row start
	call PRINT	; print the string
	ex (sp),hl	; HL = row start, row start = string pointer
	ld de,0040h	; next row
	add hl,de
	ex de,hl	; DE = next row
	pop hl	; HL = next string
	jp INSTR_LOOP

; Clear both tables, put the labels on the bottom rows, zero the counts.
CLEAR_TABLES:
	ld hl,SAUCERS	; clear SAUCERS and SHOTS: 136 bytes
	ld a,88h
CLEAR_LOOP:
	ld (hl),00h
	inc hl
	dec a
	jp nz,CLEAR_LOOP
	dec a	; A = FFh...
	ld (SAUCERS_END),a	; ... the end mark of SAUCERS (SHOTS keeps its own from the file)
	ld hl,TXT_HITS	; "HITS"
	ld de,VIDEO+897	; row 14, column 1
	call PRINT	; print the string
	ld hl,TXT_SHOTS	; "SHOTS"
	ld de,VIDEO+961	; row 15, column 1
	call PRINT	; print the string
	ld hl,TXT_SCORE	; "SCORE"
	ld de,VIDEO+947	; row 14, column 51
	call PRINT	; print the string
	ld hl,TXT_TIME	; "TIME"
	ld de,VIDEO+1011	; row 15, column 51
	call PRINT	; print the string
	ld hl,0000h	; SCORE, HITS and SHOTS to 0
	ld (SCORE),hl
	ld (HIT_COUNT),hl
	ld (SHOT_COUNT),hl
	ld a,03h	; cannon straight up
	ld (AIM),a
	call DRAW_CANNON	; draw the cannon (A = 3)
	sub a	; no shot loading
	ld (LOADING),a
	ld a,0FFh	; extra time still to come
	ld (EXTRA_LEFT),a

; After GAME OVER the demonstration pauses (30 WAITs of 255 DELAYs) and starts
; again by itself, at difficulty 1: WAIT leaves A = 1.
	ld a,(DEMO)	; the demonstration restarting after GAME OVER?
	and a
	jp z,TITLE_KEY
	ld d,1Eh	; 30 x ...
DEMO_WAIT:
	ld e,0FFh	; ... 255 DELAYs
	call WAIT	; pause E DELAYs
	dec d
	jp nz,DEMO_WAIT
	jp BEGIN	; then start, with A = 1 from WAIT: difficulty 1

;---------------------------------------------------------------
; WAIT — pause: e passes of delay
;
; In:        E = number of DELAYs (1-255; 0 means 256)
; Out:       A = 1
; Changes:   A, E; flags S Z H P/V N
; Preserves: B, C (register), D, H, L, IX, IY; flags C
;            [static + measured: 1515 calls, 1/1 branches]
; Stack:     4 bytes max, callees included  [static]
; Cycles:    observed 23199-1181449 T-states (1515 calls)  [measured]
; Exit:      RET
; Calls:     DELAY
; Called from: TITLE (43AEh), MAIN_LOOP (4465h), UPDATE (493Eh), UPDATE (4950h), UPDATE (495Dh)
; Jumped to from: WAIT (43BCh), FLASH (4A6Fh)
;---------------------------------------------------------------
WAIT:
	call DELAY	; one DELAY
	dec e	; E times
	jp nz,WAIT	; go to: pause E DELAYs
	ld a,01h	; A = 1
	ret

; Wait for the player: D for the demonstration, 1-9 to play; anything else is ignored.
TITLE_KEY:
	call GET_KEY	; a key?
	jp z,TITLE_KEY
	cp 44h	; 'D'?
	jp z,START_DEMO	; demonstration
	cp 31h	; below '1'?
	jp c,TITLE_KEY
	cp 3Ah	; above '9'?
	jp nc,TITLE_KEY

;---------------------------------------------------------------
; BEGIN — start a game (or the demonstration) at difficulty a: sets pace and the
;
; three timers, blanks the playfield (the instructions vanish), sets TIME
; to 90 and enters the main loop.
; In:        A = the key, '1'-'9'; 'D' gives 4; the demonstration's restart passes 1
; Changes:   nothing
; Preserves: A, B, C (register), D, E, H, L, IX, IY; flags S Z H P/V N C
;            [static]
; Memory:    writes CLOCK_TIMER, LAUNCH_TIMER, PACE, SAUCER_TIMER, SHOT_TIMER, TIME; reads TIME
; Stack:     18 bytes max, callees included  [static]
; Cycles:    not called in the scenarios
; Calls:     WAIT, DO_KEY, DRAW_CANNON, UPDATE, FLASH, SHOW_COUNTS, TICK_CLOCK, PRINT, PRINT_BCD, DELAY, GET_KEY, RANDOM
; Jumped to from: TITLE (43B5h), TITLE (449Ch)
;---------------------------------------------------------------
BEGIN:
	and 0Fh	; '1'-'9' to 1-9 ('D' gives 4)
	add a,01h	; d+1: SHOT_TIMER first runs out after d+1 passes
	ld (SHOT_TIMER),a
	ld (LAUNCH_TIMER),a	; and LAUNCH_TIMER
	rlca	; 2(d+1)
	add a,02h	; PACE = 2d+4: 6 (hard) to 22 (easy)
	ld (PACE),a
	ld (SAUCER_TIMER),a	; SAUCER_TIMER
	add a,0CCh	; CLOCK_TIMER = PACE+204 passes per unit of TIME
	ld (CLOCK_TIMER),a
	ld b,20h	; blank the playfield: the instructions go
	call FLASH	; fill the playfield with B
	ld a,90h	; 90 seconds, in BCD
	ld (TIME),a

; New TIME: 90 at the start, 20 more for extra time.
NEW_TIME:
	ld a,02h	; 2 digits
	ld hl,(TIME)	; TIME
	ld de,VIDEO+1020	; row 15, column 60
	call PRINT_BCD	; print A BCD digits of HL

;---------------------------------------------------------------
; MAIN_LOOP — one pass: read a key (in the demonstration, perhaps invent one), move
;
; everything (UPDATE), show the counts, DELAY, show the time (TICK_CLOCK).
; TICK_CLOCK returns Z when TIME has gone past 00; then the game either
; gives extra time (once, if the score is 400 or more) or ends.
; The pass is the game's unit of time; see the speeds under BEGIN.
; Changes:   nothing
; Preserves: A, B, C (register), D, E, H, L, IX, IY; flags S Z H P/V N C
;            [static]
; Memory:    writes EXTRA_LEFT, TIME; reads DEMO, EXTRA_LEFT, SCORE_HI, TIME
; Stack:     18 bytes max, callees included  [static]
; Cycles:    not called in the scenarios
; Calls:     WAIT, DO_KEY, DRAW_CANNON, UPDATE, FLASH, SHOW_COUNTS, TICK_CLOCK, PRINT, PRINT_BCD, DELAY, GET_KEY, RANDOM
; Jumped to from: MAIN_LOOP (4438h)
;---------------------------------------------------------------
MAIN_LOOP:
	call GET_KEY	; a key just pressed?
	call nz,DO_KEY	; yes: act on it

; The demonstration presses keys for itself: about 4 passes in 256 it picks one of
; 'Z' (fire), '.', ',' (turn) or 'Z' from DEMO_KEYS.
	ld a,(DEMO)	; the demonstration?
	and a
	jp z,MOVE_ALL
	call RANDOM	; roll for a key
	and 0FFh	; AND 0FFh only sets Z (for A = 0)
	jp z,MOVE_ALL
	cp 05h	; 1-4: press DEMO_KEYS[A-1]
	jp nc,MOVE_ALL
	ld hl,DEMO_KEYS	; the demonstration's keys
	dec a
	add a,l
	ld l,a
	ld a,h
	adc a,00h
	ld h,a
	ld a,(hl)	; Z, ., , or Z
	call DO_KEY	; press it
MOVE_ALL:
	call UPDATE	; move everything
	call SHOW_COUNTS	; print the counts
	call DELAY	; the pacing delay
	call TICK_CLOCK	; print TIME and count it down
	jp nz,MAIN_LOOP	; until TIME runs out

; TIME is up.
TIME_UP:
	ld a,(EXTRA_LEFT)	; extra time still to give?
	and a
	jp z,GAME_OVER
	ld a,(DEMO)	; the demonstration always gets it
	and a
	jp nz,EXTRA_TIME
	ld a,(SCORE_HI)	; otherwise only for 400 or more
	cp 04h	; (SCORE_HI is the hundreds and thousands digits: 04 = 400)
	jp nc,EXTRA_TIME

; GAME OVER. In the demonstration, wait and start again from TITLE.
GAME_OVER:
	ld hl,TXT_GAME_OVER	; "* *  G A M E  O V E R  * *"
	ld de,VIDEO+597	; row 9, column 21
	call PRINT	; print the string
	ld a,(DEMO)
	and a
	jp z,WAIT_ENTER
	ld d,1Eh	; 30 x 255 DELAYs
DEMO_OVER:
	ld e,0FFh
	call WAIT	; pause E DELAYs
	dec d
	jp nz,DEMO_OVER
	jp TITLE	; the demonstration goes round again, keeping its 7Fh
WAIT_ENTER:
	call GET_KEY	; wait for ENTER
	jp z,WAIT_ENTER
	cp 0Dh
	jp nz,WAIT_ENTER
	jp START	; a new game

; EXTRA TIME: 20 more, once.
EXTRA_TIME:
	ld a,20h	; 20 more seconds
	ld (TIME),a
	sub a	; extra time used
	ld (EXTRA_LEFT),a
	ld hl,TXT_EXTRA	; "EXTRA TIME"
	ld de,VIDEO+1005	; row 15, column 45
	call PRINT	; print the string
	jp NEW_TIME

; D: the demonstration. Doubles the chance of new saucers (SELF-MODIFIES 4514h)
; and starts at difficulty 4 ('D' is 44h; AND 0Fh gives 4).
START_DEMO:
	ld a,7Fh	; the spawn mask for the demonstration
	ld (SPAWN_MASK+1),a	; SELF-MODIFIES 4514h: AND 7Fh doubles the chance of a saucer
	ld a,01h	; DEMO = 1
	ld (DEMO),a
	jp BEGIN	; start with A = 'D'

;---------------------------------------------------------------
; DO_KEY — act on a key. 1-9 change the difficulty (the new pace takes effect as the
;
; timers next reload). While no shot is being loaded: '.' turns the cannon
; right, ',' left. R restarts. Anything else fires, if the cannon is not
; already loading a shot.
; The comparison is with the codes for ',' and '.', 2Ch and 2Eh. The title
; screen's '<' and '>' are those keys with SHIFT, 3Ch and 3Eh, which fire;
; the arrow keys the manual names give 08h and 09h, which also fire.
; In:        A = key code (not 0)
; Changes:   A, B, C (register), D, E, H, L; flags S Z H P/V N C
;            (on some paths only: B, C (register), D, E, H, L)
; Preserves: IX, IY
;            [static + measured: 3610 calls, 9/9 branches]
; Memory:    writes LOADING, PACE; reads AIM, LOADING
; Stack:     2 bytes max, callees included  [static]
; Cycles:    observed 99-3034483 T-states (3610 calls)  [measured]
; Exit:      RET, or JP START on R
; Calls:     PRINT
; Called from: MAIN_LOOP (4407h), MAIN_LOOP (4429h)
;---------------------------------------------------------------
DO_KEY:
	cp 31h	; below '1'?
	jp c,NOT_DIGIT
	cp 3Ah	; above '9'?
	jp nc,NOT_DIGIT
	and 0Fh	; 1-9 to 1-9 ...
	add a,01h
	rlca
	add a,02h	; ... PACE = 2d+4 (the timers keep their counts)
	ld (PACE),a
	ret
NOT_DIGIT:
	ld b,a	; keep the key
	ld a,(LOADING)	; a shot loading (LOADING)?
	and a
	ld a,b
	jp nz,NOT_AIM	; then the cannon cannot turn: only R counts
	cp 2Eh	; '.' (the '>' key unshifted)?
	jp nz,NOT_RIGHT
	ld a,(AIM)	; turn right, up to 5
	cp 05h
	ret nc
	inc a

;---------------------------------------------------------------
; SET_AIM — store a new aim and draw the cannon pointing that way (falls into
;
; DRAW_CANNON).
; In:        A = new AIM, 1-5
; Changes:   A, B, C (register), D, E, H, L; flags S Z H P/V N C
; Preserves: IX, IY
;            [static]
; Memory:    writes AIM
; Stack:     2 bytes max, callees included  [static]
; Cycles:    not called in the scenarios
; Exit:      falls into DRAW_CANNON
; Calls:     PRINT
; Jumped to from: DO_KEY (44FAh)
;---------------------------------------------------------------
SET_AIM:
	ld (AIM),a	; new AIM

;---------------------------------------------------------------
; DRAW_CANNON — draw the cannon for aim: three rows of 11 characters from cannon_gfx,
;
; at row 13, 14 and 15, column 26 (the 33 bytes for aim n start at
; CANNON_GFX + 33*(n-1)).
; In:        A = AIM (1-5)
; Changes:   A, B, C (register), D, E, H, L; flags S Z H P/V N C
; Preserves: IX, IY
;            [static + measured: 12 calls, 0/0 branches]
; Stack:     2 bytes max, callees included  [static]
; Cycles:    1606 T-states every call (12 calls)  [measured]
; Exit:      RET
; Calls:     PRINT
; Called from: TITLE (4397h)
;---------------------------------------------------------------
DRAW_CANNON:
	dec a	; A = AIM - 1
	ld b,a
	rlca
	rlca
	rlca
	rlca
	rlca	; A = 32(AIM-1)
	add a,b	; + (AIM-1) = 33(AIM-1): 33 bytes per picture
	ld hl,CANNON_GFX	; the cannon pictures
	ld c,a
	ld b,00h
	add hl,bc
	ld de,VIDEO+858	; row 13, column 26
	call PRINT	; first row
	ld de,VIDEO+922	; row 14
	call PRINT	; second row
	ld de,VIDEO+986	; row 15
	call PRINT	; third row
	ret
NOT_RIGHT:
	cp 2Ch	; ',' (the '<' key unshifted)?
	jp nz,NOT_AIM
	ld a,(AIM)	; turn left, down to 1
	cp 02h
	ret c
	dec a
	jp SET_AIM
NOT_AIM:
	cp 52h	; 'R'?
	jp nz,FIRE
	jp START	; restart
FIRE:
	ld a,(LOADING)	; any other key: fire, if no shot is loading
	and a
	ret nz
	ld a,04h	; start loading: the shot will climb the barrel
	ld (LOADING),a
	ret

;---------------------------------------------------------------
; UPDATE — move the world one pass. three independent clocks, all counted in passes:
;
;   every pass        maybe start a new saucer (SPAWN)
;   SAUCER_TIMER = 0  move the saucers (MOVE_SAUCERS), reload PACE
;   SHOT_TIMER = 0    move the shots and fragments (MOVE_SHOTS)
;   LAUNCH_TIMER = 0  move a loading shot up the barrel (LAUNCH)
; This is the heart of the program; the chapter "The Screen Is the World"
; walks through it.
; In:        nothing
; Changes:   A, B, C (register), D, E, H, L; flags S Z H P/V N C
;            (on some paths only: B, C (register), D, E, H, L)
; Preserves: IX, IY
;            [static + measured: 113184 calls, 80/89 branches]
; Memory:    writes AIM, AIM_SAVE, BIG_TURN, BOOM_COUNT, CUR_REC, HIT_ADJUST, HIT_ADJUST+1, HIT_COUNT, LAUNCH_TIMER, LIGHTS_BIG, LIGHTS_SMALL, LOADING, MOVER_CHAR, NEW_LEAD, NEW_RIGHT, SAUCER_TIMER, SCORE, SHOT_COUNT, SHOT_COUNT+1, SHOT_TIMER; reads AIM, AIM_SAVE, BIG_TURN, BOOM_COUNT, CUR_REC, HIT_ADJUST, HIT_COUNT, LAUNCH_TIMER, LIGHTS_BIG, LIGHTS_SMALL, LOADING, MOVER_CHAR, NEW_LEAD, NEW_LEAD+1, NEW_RIGHT, NEW_RIGHT+1, PACE, SAUCER_TIMER, SCORE, SHOT_COUNT, SHOT_COUNT+1, SHOT_TIMER
; Stack:     16 bytes max, callees included  [static]
; Cycles:    observed 1852-765831 T-states (113184 calls)  [measured]
; Exit:      RET
; Calls:     WAIT, DRAW_SAUCER, FLASH, DRAW_ROW, DRAW_ROWS, RANDOM
; Called from: MAIN_LOOP (442Ch)
;---------------------------------------------------------------

; SPAWN. One chance in 256 each pass (two in the demonstration) of a new saucer.
; Type: 1 small, 2 big, 3 super; RANDOM picks 1, 2 or 3 with 3 kept only one time
; in 16, so 16 : 16 : 1. Side: left or right. Row: one of four (rows 2-3, 4-5,
; 6-7 or 8-9). The saucer is not started if its first cells are not blank.
UPDATE:
	call RANDOM	; a new saucer this pass?
SPAWN_MASK:
	and 0FFh	; SELF-MODIFIED: AND 0FFh, or AND 7Fh in the demonstration
	cp 01h	; yes if the result is 1: 1 in 256 (2 in 256)
	jp nz,MOVE_SAUCERS
PICK_TYPE:
	call RANDOM	; type: 1, 2 or 3 ...
	and 03h
	jp z,PICK_TYPE	; (0 is rolled again)
	cp 03h	; a 3 ...
	jp nz,PICK_SIDE
	call RANDOM	; ... is kept only if a second roll ...
	and 0Fh
	cp 03h	; ... gives 3 in its low 4 bits, else start over
	jp nz,PICK_TYPE
PICK_SIDE:
	ld b,a	; B = type
	call RANDOM	; which side?
	and 01h
	jp z,SPAWN_LEFTWARD	; bit 0 = 0: from the right
	call RANDOM	; row: (random AND E0h OR 20h) x 2 =
	and 0E0h
	or 20h
	ld l,a	;   40h, C0h, 140h or 1C0h ...
	ld h,00h
	add hl,hl
	ld de,VIDEO+129	; ... + row 2 column 1: rows 3, 5, 7 or 9, column 1 (the lights row)
	add hl,de
	ex de,hl
	ld a,b
	ld c,06h	; 6 cells along: the lead cell
	ld l,c
	ld h,00h
	add hl,de
	ld (NEW_LEAD),hl	; NEW_LEAD
	ld a,(hl)	; all clear where it starts?
	cp 20h
	jp nz,MOVE_SAUCERS
	ld a,(de)	; (lead cell, left end and the cell 2 left of the lead)
	cp 20h
	jp nz,MOVE_SAUCERS
	dec hl
	dec hl
	ld a,(hl)
	cp 20h
	jp nz,MOVE_SAUCERS
	ld hl,SAUCERS	; find a free record
FIND_FREE_R:
	ld a,(hl)	; FFh: table full, no saucer
	cp 0FFh
	jp z,MOVE_SAUCERS
	and a	; 0: free
	jp z,START_RIGHTWARD
	inc hl
	inc hl
	inc hl
	inc hl
	inc hl
	jp FIND_FREE_R
START_RIGHTWARD:
	ld a,b	; type, moving right (bit 7)
	or 80h
	ld (hl),a
	inc hl
	ld a,(NEW_LEAD)	; bytes 1-2: lead cell
	ld (hl),a
	inc hl
	ld a,(NEW_LEAD+1)
	ld (hl),a
	inc hl
	ld (hl),e	; bytes 3-4: left end
	inc hl
	ld (hl),d
	ld hl,0FFC0h	; one row up: the dome
	add hl,de
	ex de,hl
	ld hl,SAUCER_TOP	; draw it
	call DRAW_SAUCER	; draw the saucer
	jp MOVE_SAUCERS

;---------------------------------------------------------------
; DRAW_SAUCER — draw a saucer: its dome (from saucer_top) in the row of de, its row of
;
; lights (SAUCER_LIGHTS_A or _B, by the type's light phase) in the row
; below. Each picture is 6 cells with a blank at both ends, so drawing a
; saucer one cell further along also wipes the cell it left: there is no
; separate erase.
; In:        B = type 1-3, DE = cell for the dome's left end,
;            HL = SAUCER_TOP (callers always pass it)
; Changes:   A, B, D, E, H, L; flags S Z H P/V N C
; Preserves: C (register), IX, IY
;            [static + measured: 15790 calls, 2/2 branches]
; Memory:    reads LIGHTS_BIG, LIGHTS_SMALL
; Stack:     10 bytes max, callees included  [static]
; Cycles:    observed 1111-1131 T-states (15790 calls)  [measured]
; Exit:      RET
; Calls:     DRAW_ROW
; Called from: UPDATE (4597h), UPDATE (463Dh), UPDATE (475Ah), UPDATE (47ABh)
;---------------------------------------------------------------
DRAW_SAUCER:
	ld a,b	; A = type - 1
	dec a
	dec b	; B = type - 1 (0 small, 1 big, 2 super)
	rlca
	rlca
	add a,b	; 4(t-1) ...
	add a,b
	add a,b	; ... + 3(t-1) = 7(t-1): 7 bytes a picture
	add a,l	; HL = SAUCER_TOP + 7(t-1)
	ld l,a
	ld a,h
	adc a,00h
	ld h,a
	push de
	push bc
	call DRAW_ROW	; the dome
	pop bc
	pop de
	ld hl,0040h	; the row below
	add hl,de
	ex de,hl
	ld hl,SAUCER_LIGHTS_A	; lights A ...
	ld a,b	; a small saucer?
	and a
	jp z,LIGHTS_SMALL_PH
	ld a,(LIGHTS_BIG)	; big or super: their phase
	jp LIGHTS_PH
LIGHTS_SMALL_PH:
	ld a,(LIGHTS_SMALL)	; small: its phase
LIGHTS_PH:
	and a	; phase 80h: lights A, 00h: lights B
	jp m,DRAW_LIGHTS
	ld hl,SAUCER_LIGHTS_B	; lights B
DRAW_LIGHTS:
	ld a,b	; HL += 7(t-1)
	rlca
	rlca
	add a,b
	add a,b
	add a,b
	add a,l
	ld l,a
	ld a,h
	adc a,00h
	ld h,a
	call DRAW_ROW	; the lights
	ret

; Start a saucer at the right edge, moving left.
SPAWN_LEFTWARD:
	call RANDOM	; row, as above ...
	and 0E0h
	or 20h
	ld l,a
	ld h,00h
	add hl,hl
	ld a,l	; ... and 39h along:
	add a,39h
	ld l,a
	ld de,VIDEO+127	; rows 3, 5, 7 or 9, column 56
	add hl,de
	ex de,hl
	ld a,b
	ld c,06h	; 6 cells along: its right end
	ld l,c
	ld h,00h
	add hl,de
	ld (NEW_RIGHT),hl	; NEW_RIGHT (never read again)
	ld a,(hl)	; all clear where it starts?
	cp 20h
	jp nz,MOVE_SAUCERS
	ld a,(de)
	cp 20h
	jp nz,MOVE_SAUCERS
	dec hl
	dec hl
	ld a,(hl)
	cp 20h
	jp nz,MOVE_SAUCERS
	ld hl,SAUCERS	; find a free record
FIND_FREE_L:
	ld a,(hl)
	cp 0FFh
	jp z,MOVE_SAUCERS
	and a
	jp z,START_LEFTWARD
	inc hl
	inc hl
	inc hl
	inc hl
	inc hl
	jp FIND_FREE_L
START_LEFTWARD:
	ld (hl),b	; type, moving left (bit 7 clear)
	inc hl	; bytes 1-2: lead cell = left end
	ld (hl),e
	inc hl
	ld (hl),d
	inc hl
	ld a,(NEW_RIGHT)	; bytes 3-4: right end (for a leftward saucer, never read)
	ld (hl),a
	inc hl
	ld a,(NEW_RIGHT+1)
	ld (hl),a
	ld hl,0FFC0h	; the dome row
	add hl,de
	ex de,hl
	ld hl,SAUCER_TOP
	call DRAW_SAUCER	; draw the saucer

; MOVE_SAUCERS: every PACE passes.
MOVE_SAUCERS:
	ld a,(SAUCER_TIMER)	; time to move the saucers?
	dec a
	ld (SAUCER_TIMER),a
	jp nz,MOVE_SHOTS
	ld a,(PACE)	; reload from PACE
	ld (SAUCER_TIMER),a
	ld a,(BIG_TURN)	; flip BIG_TURN
	xor 80h
	ld (BIG_TURN),a
	jp z,FLIP_SMALL	; flipped to 0: the big lights stay
	ld a,(LIGHTS_BIG)	; flipped to 80h: flip the big lights
	xor 80h
	ld (LIGHTS_BIG),a
FLIP_SMALL:
	ld a,(LIGHTS_SMALL)	; flip the small lights every step
	xor 80h
	ld (LIGHTS_SMALL),a
	ld hl,SAUCERS	; every saucer
SAUCER_LOOP:
	ld a,(hl)	; FFh: done
	cp 0FFh
	jp z,MOVE_SHOTS
	and a	; 0: free
	jp nz,ACTIVE_SAUCER
NEXT_SAUCER:
	inc hl
	inc hl
NEXT_SAUCER_3:
	inc hl
	inc hl
	inc hl
	jp SAUCER_LOOP

; A saucer record: types 5, 6 and 7 are the three pictures of an explosion
; (from BOOM_GFX), 8 removes it.
ACTIVE_SAUCER:
	and 7Fh	; type without the direction bit
	ld b,a
	ld (CUR_REC),hl	; CUR_REC
	cp 05h	; 1-4: a saucer
	jp c,SAUCER_TURN
	cp 08h	; 8: the explosion is over
	jp z,BOOM_END
	sub 05h	; 5, 6, 7: picture 0, 1, 2 ...
	inc (hl)	; ... and the next one next step
	ld hl,BOOM_GFX	; BOOM_GFX + 18 x picture
	or a
	rlca
	ld c,a
	rlca
	rlca
	rlca
	add a,c
	add a,l
	ld l,a
	ld a,h
	adc a,00h
	ld h,a
	push hl	; push the picture
	ld hl,(CUR_REC)	; its record
	ld a,(hl)
BOOM_FRAME:
	and a	; moving right?
	inc hl
	ld e,(hl)	; bytes 1-2
	inc hl
	ld d,(hl)
	jp p,BOOM_DRAW	; leftward: draw at its left end (bytes 1-2)
	inc hl
	ld e,(hl)	; rightward: at its left end (bytes 3-4)
	inc hl
	ld d,(hl)
BOOM_DRAW:
	ld hl,0FFC0h	; one row up
	add hl,de
	ex de,hl
	pop hl
	ld b,02h	; two rows of 6
	call DRAW_ROWS	; print B rows
	ld hl,(CUR_REC)
	jp NEXT_SAUCER
BOOM_END:
	ld a,(hl)	; the type
	ld hl,BLANK6	; BLANK6, to wipe it
	push hl
	ld hl,(CUR_REC)
	ld (hl),00h	; free the record
	jp BOOM_FRAME	; and draw the blanks where it was

; Small saucers (type 1) move every step; big and super ones every other step.
SAUCER_TURN:
	cp 01h	; a small saucer moves every step
	jp z,SAUCER_RIGHT
	ld a,(BIG_TURN)	; the others only on BIG_TURN
	and a
	jp z,NEXT_SAUCER

; A saucer moving right. Its lead cell is the cell just past its picture (left end + 6).
SAUCER_RIGHT:
	ld a,(hl)	; moving right?
	and 80h
	jp z,SAUCER_LEFT
	inc hl	; its lead cell (left end + 6, just past its picture) ...
	ld e,(hl)
	inc hl
	ld d,(hl)
	inc de	; ... one further: left end + 7
	ld a,e	; into column 63, the wall?
	and 3Fh
	cp 3Fh
	jp nz,SAUCER_LOOK_R
	push hl	; it escapes
	inc hl	; its left end
	ld e,(hl)
	inc hl
	ld d,(hl)

; Escaped: wipe it, free the record, one point off (SCORE stops at 0000).
	ld hl,BLANK6	; wipe the lights row ...
ESCAPED:
	push de
	call DRAW_ROW	; print one row
	pop de
	ld hl,0FFC0h
	add hl,de
	ex de,hl
	ld hl,BLANK6	; ... and the dome row
	call DRAW_ROW	; print one row
	pop hl	; the record
	dec hl
	dec hl
	push hl
	ld (hl),00h	; free it
	ld hl,(SCORE)	; SCORE - 1, unless it is 0000:
	ld a,l	; tests only the low byte: at 0100, 0200 ... an escape costs nothing
	or l
	jp z,SET_SCORE
	ld a,l	; add 9999 in BCD ...
	add a,99h
	daa
	ld l,a
	jp c,SET_SCORE	; ... low digits borrowed? then done
	ld a,h	; UNREACHED: L is never 00 here (4714h), so the low digits always carry
	add a,99h	; UNREACHED
	ld h,a	; UNREACHED
SET_SCORE:
	ld (SCORE),hl
	pop hl
	jp SAUCER_LOOP

; Look ahead: a blank or a shot ('0' or '!') is fine; anything else (another
; saucer, a fragment) and the saucer blows up, for no points. Moving right it
; looks at left end + 7, a cell beyond the one its moved picture will cover;
; moving left (4783h) it looks at the cell its own left blank will take. So a
; rightward saucer never gets closer than one blank cell to what is ahead.
SAUCER_LOOK_R:
	ld a,(de)	; what is at left end + 7? One cell beyond where its right blank will go (a leftward saucer reads the cell its own blank will take: rightward ones stop a cell sooner)
	dec de
	cp 20h	; blank: move
	jp z,SAUCER_STEP_R
	cp 30h	; a shot's '0': move (the shot finds the saucer, not the other way round)
	jp z,SAUCER_STEP_R
	cp 21h	; a shot's '!': move
	jp z,SAUCER_STEP_R
	ld hl,(CUR_REC)	; anything else: blown up, no points
	ld a,(hl)
	and 80h
	or 05h	; type 5, keeping the direction bit
	ld (hl),a
	jp NEXT_SAUCER
SAUCER_STEP_R:
	inc hl	; step right:
	inc de	; the new lead cell
	push de
	ld e,(hl)	; the left end ...
	inc hl
	ld d,(hl)
	inc de	; ... one further
	dec hl
	dec hl
	ex (sp),hl	; swap: keep the record pointer
	push hl
	ld hl,0FFC0h	; dome row
	add hl,de
	ex de,hl
	ld hl,SAUCER_TOP	; draw it there; its blank left edge wipes the old left cell
	call DRAW_SAUCER	; draw the saucer
	pop de	; new lead cell
	pop hl
	ld (hl),d	; into bytes 1-2
	dec hl
	ld (hl),e
	inc hl
	inc hl
	inc (hl)	; bytes 3-4 + 1 (16-bit)
	inc hl
	jp nz,STEPPED_R
	inc (hl)	; UNREACHED: a rightward saucer's left end stays inside one 256-byte page (rows 3, 5, 7, 9, columns 1-57)
STEPPED_R:
	dec hl
	dec hl
	dec de
	jp NEXT_SAUCER_3

; A saucer moving left. Its lead cell is its own left end.
SAUCER_LEFT:
	inc hl	; moving left:
	ld e,(hl)
	inc hl
	ld d,(hl)
	dec de	; its left end, one further
	ld a,e	; into column 0, the wall?
	and 3Fh
	jp nz,SAUCER_LOOK_L
	push hl	; it escapes
	ld hl,BLANK6
	inc de
	jp ESCAPED
SAUCER_LOOK_L:
	ld a,(de)	; what is in the new left cell?
	inc de
	cp 20h
	jp z,SAUCER_STEP_L
	cp 30h
	jp z,SAUCER_STEP_L
	cp 21h
	jp z,SAUCER_STEP_L
	ld hl,(CUR_REC)	; anything but blank, '0' or '!': blown up
	ld a,(hl)
	and 80h
	or 05h
	ld (hl),a
	jp NEXT_SAUCER
SAUCER_STEP_L:
	dec de	; step left:
	push hl
	push de
	ld hl,0FFC0h	; dome row
	add hl,de
	ex de,hl
	ld hl,SAUCER_TOP	; draw it there; its blank right edge wipes the old right cell
	call DRAW_SAUCER	; draw the saucer
	pop de
	pop hl
	ld (hl),d	; into bytes 1-2
	dec hl
	ld (hl),e
	inc hl
	inc hl
	inc (hl)	; bytes 3-4 + 1: a leftward saucer's are never read
	inc hl
	jp nz,STEPPED_L
	inc (hl)
STEPPED_L:
	dec hl
	dec hl
	jp NEXT_SAUCER_3

; MOVE_SHOTS: every PACE/2-1 passes. Each record in SHOTS is a shot or a fragment:
;   state 1, 2      a shot: it moves on 2 (drawn '0'), and is drawn '!' on 1,
;                   so it moves every other step and flickers between them
;   state d*16+n    a fragment going direction d (1-12), n counts 8 down to 3
; A shot moves the way AIM points at that moment. That one fact is the
; steering: turning the cannon turns every shot in the air.
MOVE_SHOTS:
	ld a,(AIM)	; keep the real AIM: fragments borrow it
	ld (AIM_SAVE),a
	ld a,(SHOT_TIMER)	; time to move the shots?
	dec a
	ld (SHOT_TIMER),a
	jp nz,LAUNCH
	ld a,(PACE)	; reload with PACE/2 - 1
	sub 02h
	rrca
	ld (SHOT_TIMER),a
	ld hl,SHOTS	; every shot
SHOT_LOOP:
	ld a,(AIM_SAVE)	; AIM back to the real one
	ld (AIM),a
	ld a,20h	; assume a shot...
	ld (MOVER_CHAR),a	; ... (MOVER_CHAR = blank until we know)
	ld a,(hl)
	cp 0FFh	; FFh: done
	jp z,LAUNCH
	ld (CUR_REC),hl	; CUR_REC
	and a	; 0: free
	jp nz,ACTIVE_SHOT
NEXT_SHOT:
	inc hl
	inc hl
	inc hl
	jp SHOT_LOOP

; A fragment: borrow AIM for its own direction (the high nibble).
ACTIVE_SHOT:
	cp 03h	; 3 or more: a fragment
	jp c,SHOT
	and 0Fh	; its count ...
	cp 03h	; ... down to 3: its time is up
	ld a,(hl)
	jp nz,FRAGMENT
	inc hl	; wipe it and free the record
	ld e,(hl)
	inc hl
	ld d,(hl)
	ld a,20h
	ld (de),a
	jp SHOT_GONE
FRAGMENT:
	dec (hl)	; count down
	rrca	; direction in the high 4 bits ...
	rrca
	rrca
	rrca
	and 0Fh
	ld (AIM),a	; ... becomes AIM for this move
	inc hl
	ld e,(hl)
	inc hl
	ld d,(hl)
	inc hl
	ld a,20h	; wipe it where it was
	ld (de),a
	ld b,2Ah	; '*'
	ld a,b
	ld (MOVER_CHAR),a	; MOVER_CHAR = fragment
	jp STEP_IT

; A shot. On state 2 it moves; on state 1 it is redrawn as '!'.
SHOT:
	dec (hl)	; a shot: count 2 -> 1 or 1 -> 0
	jp z,SHOT_MOVES
	inc hl	; on 1: just redraw it ...
	ld e,(hl)
	inc hl
	ld d,(hl)
	inc hl
	ld a,21h	; ... as '!'
	ld (de),a
	jp SHOT_LOOP
SHOT_MOVES:
	ld (hl),02h	; on 0: back to 2 ...
	inc hl
	ld e,(hl)
	inc hl
	ld d,(hl)
	inc hl
	ld a,20h	; ... wipe it where it was ...
	ld (de),a
	ld b,30h	; ... and it will be a '0'

; Move it: STEP[AIM] is added to the cell (AIM is the cannon's, or the
; fragment's borrowed one).
STEP_IT:
	push hl	; move it the way AIM points:
	ld hl,STEP	; STEP[AIM]
	ld a,(AIM)
	dec a
	rlca
	add a,l
	ld l,a
	ld a,h
	adc a,00h
	ld h,a
	ld a,(hl)
	inc hl
	ld h,(hl)
	ld l,a
	add hl,de	; DE = the next cell
	ex de,hl
	pop hl
	ld a,d	; into row 0?
	cp 3Ch
	jp nz,LOOK_AHEAD
	ld a,e
	cp 40h
	jp nc,LOOK_AHEAD

; Reached the top row: the shot is gone. A shot (not a fragment) costs 2 points.
	ld a,(MOVER_CHAR)	; a fragment just goes
	cp 2Ah
	jp z,SHOT_GONE
	ld hl,(SCORE)	; a shot: SCORE - 2 (add 9998 in BCD) ...
	ld a,l
	add a,98h
	daa
	ld l,a
	jp c,STORE_SCORE
	ld a,h
	add a,99h
	daa
	ld h,a
	cp 98h	; ... and below 0000? then 0000
	jp c,STORE_SCORE
	ld hl,0000h
STORE_SCORE:
	ld (SCORE),hl
SHOT_GONE:
	ld hl,(CUR_REC)	; free the record
	ld (hl),00h
	jp NEXT_SHOT

; Look at the cell it is moving into. Blank: move (4A72). Anything else is a hit.
LOOK_AHEAD:
	ld a,(de)	; is the next cell blank?
	cp 20h
	jp z,MOVE_INTO	; yes: just move
	push hl
	ld a,03h	; three explosion pictures
	ld (BOOM_COUNT),a
	ld hl,SAUCERS	; which saucer is there?

; Find the saucer in that cell: same row, and the cell is at its left end or
; up to 5 cells to the right of it. (If no saucer is there, a wall or another
; shot was hit: the explosion is drawn anyway, and no points are scored.)
FIND_TARGET:
	sub a	; HIT_ADJUST = 0 (it stays 0)
	ld (HIT_ADJUST),a
	ld (HIT_ADJUST+1),a
	ld a,(hl)	; FFh: none; still explode (a wall, another shot)
	cp 0FFh
	jp z,BOOM_HERE
	and 7Fh	; types 4 and up are not targets (exploding)
	cp 04h
	ld a,(hl)
	jp c,TARGET_LIVE
	inc hl
	inc hl
NEXT_TARGET:
	inc hl
	inc hl
	inc hl
	jp FIND_TARGET
TARGET_LIVE:
	inc hl	; BC = its left end:
	ld c,(hl)	; bytes 1-2 for a leftward saucer
	inc hl
	ld b,(hl)
	and a
	jp p,TARGET_ROW
	inc hl	; bytes 3-4 for a rightward one
	ld c,(hl)
	inc hl
	ld b,(hl)
	dec hl
	dec hl
TARGET_ROW:
	ld a,b	; same row?
	cp d
	jp nz,NEXT_TARGET
	ld a,c	; its left end?
	cp e
	jp z,TARGET_HIT
	ld b,05h	; or one of the next 5 cells?
TARGET_SPAN:
	inc a
	cp e
	jp z,TARGET_HIT
	dec b
	jp nz,TARGET_SPAN
	jp NEXT_TARGET
TARGET_HIT:
	ld e,c	; hit it. E = its left end (where the explosion goes)
	dec hl
	dec hl
	ld a,(hl)	; its type
	and 7Fh
	cp 01h
	jp z,SCORE_SMALL
	cp 02h
	jp z,SCORE_BIG
	cp 03h
	jp z,SUPER_HIT
SCORE_SMALL:
	push hl	; small: SCORE + 20
	ld hl,(SCORE)
	ld a,l
	add a,20h
ADD_SCORE:
	daa
	ld l,a
	ld a,h
	adc a,00h
	daa
	ld h,a
	ld (SCORE),hl
	pop hl
	jp SET_BOOM
SCORE_BIG:
	push hl
	ld hl,(SCORE)	; big: SCORE + 10
	ld a,l
	add a,10h
	jp ADD_SCORE
SET_BOOM:
	ld a,(hl)	; the saucer starts its own explosion, type 5
	and 80h
	or 05h
	ld (hl),a
	ld hl,(HIT_COUNT)	; HITS + 1
	ld a,l
	add a,01h
	daa
	ld l,a
	ld a,h
	adc a,00h
	daa
	ld h,a
	ld (HIT_COUNT),hl
	ld hl,(HIT_ADJUST)	; HIT_ADJUST is 0: DE unchanged
	add hl,de
	ex de,hl

; The explosion, drawn with pauses while the whole game waits, then wiped: at the
; saucer's left end if one was found (48E6h), else at the cell hit. One row of
; each of the three BOOM_GFX pictures.
BOOM_HERE:
	push de	; draw the explosion at the hit:
	ld hl,BOOM_GFX	; " *#* " on the lights row (# = a solid block)
	call DRAW_ROW	; print one row
	ld e,05h	; pause 5
	call WAIT	; pause E DELAYs
	pop de
	push de
	ld hl,0FFC0h
	add hl,de
	ex de,hl
	ld hl,BOOM_GFX+18	; "*****" on the dome row
	call DRAW_ROW	; print one row
	ld e,05h
	call WAIT	; pause E DELAYs
	pop de
	push de
	ld hl,BOOM_GFX+36	; the sides of the POW box (the first row of the third picture) on the lights row
	call DRAW_ROW	; print one row
	ld e,05h
	call WAIT	; pause E DELAYs
	pop de
	ld a,(BOOM_COUNT)	; BOOM_COUNT - 1: never tested here (vestigial; SUPER_FLASH uses it)
	dec a
	ld (BOOM_COUNT),a
	ld hl,BLANK6	; wipe both rows
	push de
	call DRAW_ROW	; print one row
	pop de
	ld hl,0FFC0h
	add hl,de
	ex de,hl
	push de
	ld hl,BLANK6
	call DRAW_ROW	; print one row
	pop de

; A shot (not a fragment), below row 1: scatter fragments. Each of the 12
; directions gets one with a chance of 4 in 16.
	ld a,(MOVER_CHAR)	; was it a fragment?
	cp 2Ah	; fragments do not scatter more
	jp z,TARGET_DONE
	ld a,d	; in rows 0-1?
	cp 3Ch
	jp nz,SCATTER
	ld a,e
	cp 80h	; then no fragments
	jp c,TARGET_DONE
SCATTER:
	ld c,0Ch	; directions 12 down to 1
SCATTER_LOOP:
	call RANDOM	; one chance in 4 for each
	and 0Fh
	cp 0Ch
	jp nc,NEW_FRAGMENT
SCATTER_NEXT:
	dec c
	jp nz,SCATTER_LOOP
	jp TARGET_DONE
NEW_FRAGMENT:
	ld a,c	; state = direction x 16 + 8
	rlca
	rlca
	rlca
	rlca
	and 0F0h
	or 08h
	ld b,a
	ld hl,SHOTS	; a free shot record
FIND_FREE_S:
	ld a,(hl)
	cp 0FFh
	jp z,TARGET_DONE	; none: no more fragments
	and a
	jp z,PUT_FRAGMENT
	inc hl
	inc hl
	inc hl
	jp FIND_FREE_S
PUT_FRAGMENT:
	ld (hl),b	; start the fragment here
	inc hl
	ld (hl),e
	inc hl
	ld (hl),d
	jp SCATTER_NEXT
TARGET_DONE:
	ld hl,(CUR_REC)	; the shot is used up
	ld (hl),00h
	pop hl
	jp SHOT_LOOP

; The super saucer: flash the screen three times, then every saucer on the
; screen is scored and removed, and every shot and fragment is cleared.
SUPER_HIT:
	ld a,03h	; flash three times:
	ld (BOOM_COUNT),a
SUPER_FLASH:
	ld b,84h	; fill with 84h (the middle-left sixth of a block lit)
	call FLASH	; fill the playfield with B
	ld b,2Bh	; then '+'
	call FLASH	; fill the playfield with B
	ld b,20h	; then blank
	call FLASH	; fill the playfield with B
	ld a,(BOOM_COUNT)
	dec a
	ld (BOOM_COUNT),a
	jp nz,SUPER_FLASH
	ld hl,SAUCERS	; every saucer:
SCORE_ALL:
	ld a,(hl)
	cp 0FFh
	jp z,CLEAR_SHOTS
	and 7Fh
	cp 01h
	jp z,ALL_SMALL
	cp 02h
	jp z,ALL_BIG
	cp 03h
	jp z,ALL_BIG
CLEAR_SAUCER:
	ld (hl),00h	; free it (everything is blank already)
	inc hl
	inc hl
	inc hl
	inc hl
	inc hl
	jp SCORE_ALL
ALL_SMALL:
	push hl	; small: +20
	ld hl,(SCORE)
	ld a,l
	add a,20h
ALL_ADD:
	daa
	ld l,a
	ld a,h
	adc a,00h
	daa
	ld h,a
	ld (SCORE),hl
	ld hl,(HIT_COUNT)	; HITS + 1
	ld a,l
	add a,01h
	daa
	ld l,a
	ld a,h
	adc a,00h
	daa
	ld h,a
	ld (HIT_COUNT),hl
	pop hl
	jp CLEAR_SAUCER
ALL_BIG:
	push hl	; big or super: +10 (the super saucer scores as a big one)
	ld hl,(SCORE)
	ld a,l
	add a,10h
	jp ALL_ADD
CLEAR_SHOTS:
	ld hl,SHOTS	; clear every shot and fragment
	ld c,3Ch	; 60 bytes
CLEAR_SHOTS_LOOP:
	ld (hl),00h
	inc hl
	dec c
	jp nz,CLEAR_SHOTS_LOOP
	pop hl	; drop the shot pointer
	jp LAUNCH

;---------------------------------------------------------------
; FLASH — fill the playfield (rows 1-12, inside the walls) with the character in b,
;
; then WAIT 5. Used three times in a row to flash the screen when the super
; saucer is hit, and once with blanks to clear the instructions.
; In:        B = character
; Changes:   A, D, E, H, L; flags S Z H P/V N C
; Preserves: B, C (register), IX, IY
;            [static + measured: 30 calls, 3/3 branches]
; Stack:     4 bytes max, callees included  [static]
; Cycles:    83572 T-states every call (30 calls)  [measured]
; Exit:      tail JP to WAIT
; Calls:     DELAY
; Called from: BEGIN (43F1h), UPDATE (49D9h), UPDATE (49DEh), UPDATE (49E3h)
;---------------------------------------------------------------
FLASH:
	ld hl,VIDEO+64	; rows 1-12
	ld de,0300h	; 768 cells
FLASH_LOOP:
	ld a,l	; column 63: the wall
	and 3Fh
	cp 3Fh
	jp z,FLASH_SKIP
	and a	; column 0: the wall
	jp z,FLASH_SKIP
	ld (hl),b	; fill
FLASH_SKIP:
	dec de
	inc hl
	ld a,d
	or e
	jp nz,FLASH_LOOP
	ld e,05h	; pause 5
	jp WAIT	; WAIT returns for us

; The cell is blank: move into it. (The test for the top row here can never be
; true: 485Dh has already caught every shot leaving row 1. The code at 4A7Eh,
; which would take 20 points off, never runs.)
MOVE_INTO:
	ld a,d	; into row 0? (never: 485Dh came first)
	cp 3Ch
	jp nz,MOVE_CHECK
	ld a,e
	cp 40h
	jp nc,MOVE_CHECK
	dec hl	; UNREACHED: free the record ...
	dec hl	; UNREACHED
	dec hl	; UNREACHED
	ld (hl),00h	; UNREACHED
	push hl	; UNREACHED
	ld hl,(SCORE)	; UNREACHED: ... and SCORE - 20 (add 9980 in BCD)
	ld a,l	; UNREACHED
	add a,80h	; UNREACHED
	daa	; UNREACHED
	ld l,a	; UNREACHED
	jp c,STORE_SCORE2	; UNREACHED
	ld a,h	; UNREACHED
	add a,99h	; UNREACHED
	daa	; UNREACHED
	ld h,a	; UNREACHED
	jp c,STORE_SCORE2	; UNREACHED
	ld hl,0000h	; UNREACHED
STORE_SCORE2:
	ld (SCORE),hl	; UNREACHED
	pop hl	; UNREACHED
	jp SHOT_LOOP	; UNREACHED
FRAGMENT_GONE:
	dec hl
	dec hl
	dec hl
	ld (hl),00h
	jp NEXT_SHOT

; A fragment that reaches columns 0-2 or 61-63, or rows 12-15, is removed instead.
MOVE_CHECK:
	ld a,(MOVER_CHAR)	; a fragment?
	cp 2Ah
	jp nz,MOVE_DRAW
	ld a,e	; column 0-2 ...
	and 3Fh
	cp 03h
	jp c,FRAGMENT_GONE
	cp 3Dh	; ... or 61-63?
	jp nc,FRAGMENT_GONE
	ld a,d	; or rows 12-15 (3F00h-3FFFh)?
	and 03h
	cp 03h
	jp z,FRAGMENT_GONE
MOVE_DRAW:
	ld a,b	; draw '0' or '*' in the new cell
	ld (de),a
	dec hl
	ld (hl),d	; and keep it in the record
	dec hl
	ld (hl),e
	inc hl
	inc hl
	jp SHOT_LOOP

; LAUNCH: every PACE/2-1 passes. A shot being loaded climbs the barrel as a
; solid block, one cell a step (LOADING 3, 2, 1); on 0 it leaves as a '0' and
; the barrel is redrawn empty. SHOTS counts it on the first step.
LAUNCH:
	ld a,(AIM_SAVE)	; AIM back to the real one
	ld (AIM),a
	ld a,(LAUNCH_TIMER)	; time for the next launch step?
	dec a
	ld (LAUNCH_TIMER),a
	ret nz
	ld a,(PACE)	; reload with PACE/2 - 1
	sub 02h
	rrca
	ld (LAUNCH_TIMER),a
	ld a,(LOADING)	; a shot loading?
	and a
	ret z
	dec a	; step it up the barrel
	ld (LOADING),a
	cp 03h	; the first step ...
	jp c,LAUNCH_DRAW
	ld a,(SHOT_COUNT)	; ... counts the shot: SHOTS + 1
	add a,01h
	daa
	ld (SHOT_COUNT),a
	and a
	jp nz,LAUNCH_DRAW
	ld a,(SHOT_COUNT+1)
	add a,01h
	daa
	ld (SHOT_COUNT+1),a
LAUNCH_DRAW:
	ld hl,BARREL	; the barrel cells for AIM: BARREL + 8(AIM-1)
	ld a,(AIM)
	dec a
	rlca
	rlca
	rlca
	add a,l
	ld l,a
	ld a,h
	adc a,00h
	ld h,a
	ld a,(LOADING)	; step 3, 2, 1, 0 ...
	ld c,a
	ld a,04h	; ... is barrel cell 1, 2, 3, 4
	sub c
BARREL_CELL:
	ld e,(hl)
	inc hl
	ld d,(hl)
	inc hl
	dec a
	jp nz,BARREL_CELL
	ld a,(LOADING)	; still loading?
	and a
	ld a,0BFh	; a solid block (BFh)
	jp nz,BARREL_PUT
	ld a,30h	; launched: a '0'
BARREL_PUT:
	ld (de),a	; into the barrel cell
	ret nz	; still loading: done
	push hl
	ld hl,SHOTS	; a free shot record
FIND_FREE_SHOT:
	ld a,(hl)
	and a
	jp z,PUT_SHOT
	inc hl
	inc hl
	inc hl
	jp FIND_FREE_SHOT
PUT_SHOT:
	ld (hl),02h	; state 2, at the mouth of the barrel
	inc hl
	ld (hl),e
	inc hl
	ld (hl),d
	ld c,03h	; blank the three cells below it
	pop hl
	dec hl
	dec hl
EMPTY_BARREL:
	dec hl
	ld d,(hl)
	dec hl
	ld e,(hl)
	ld a,20h
	ld (de),a
	dec c
	jp nz,EMPTY_BARREL
	ret

;---------------------------------------------------------------
; SHOW_COUNTS — print score (4 digits), hits and shots (3 digits each) in the bottom rows
;
; In:        nothing
; Changes:   A, B, C (register), D, E, H, L; flags S Z H P/V N C
; Preserves: IX, IY
;            [static + measured: 113182 calls, 0/0 branches]
; Memory:    reads HIT_COUNT, SCORE, SHOT_COUNT
; Stack:     2 bytes max, callees included  [static]
; Cycles:    977 T-states every call (113182 calls)  [measured]
; Exit:      RET
; Calls:     PRINT_BCD
; Called from: MAIN_LOOP (442Fh)
;---------------------------------------------------------------
SHOW_COUNTS:
	ld de,VIDEO+954	; row 14, column 58
	ld hl,(SCORE)
	ld a,04h	; 4 digits
	call PRINT_BCD	; print A BCD digits of HL
	ld de,VIDEO+903	; row 14, column 7
	ld hl,(HIT_COUNT)	; HITS
	ld a,03h	; 3 digits
	call PRINT_BCD	; print A BCD digits of HL
	ld de,VIDEO+967	; row 15, column 7
	ld hl,(SHOT_COUNT)	; SHOTS
	ld a,03h
	call PRINT_BCD	; print A BCD digits of HL
	ret

;---------------------------------------------------------------
; TICK_CLOCK — print time; count down clock_timer and, when it reaches 0, reload it with
;
; PACE+204 and take one off TIME. After the extra time has been used,
; EXTRA TIME flashes, on and off with each tick.
; In:        nothing
; Out:       Z set when TIME has just gone from 00 to 99 (time is up) (contract)
; Changes:   A, B, C (register), D, E, H, L; flags S Z H P/V N C
; Preserves: IX, IY
;            [static + measured: 113179 calls, 3/3 branches]
; Memory:    writes BLINK, CLOCK_TIMER, TIME; reads BLINK, CLOCK_TIMER, EXTRA_LEFT, PACE, TIME
; Stack:     6 bytes max, callees included  [static]
; Cycles:    observed 273-1064 T-states (113179 calls)  [measured]
; Exit:      RET
; Calls:     PRINT_BCD, DRAW_ROW
; Called from: MAIN_LOOP (4435h)
;---------------------------------------------------------------
TICK_CLOCK:
	ld de,VIDEO+1020	; row 15, column 60
	ld hl,(TIME)
	ld a,02h	; 2 digits
	call PRINT_BCD	; print A BCD digits of HL
	ld a,(CLOCK_TIMER)	; a second gone?
	dec a
	ld (CLOCK_TIMER),a
	ret nz
	ld a,(PACE)	; reload: PACE + 204
	add a,0CCh
	ld (CLOCK_TIMER),a
	ld a,(EXTRA_LEFT)	; extra time already given?
	and a
	jp nz,TIME_DOWN
	ld a,(BLINK)	; then flash EXTRA TIME:
	xor 80h	; flip
	ld (BLINK),a
	ld hl,TXT_EXTRA	; "EXTRA TIME" ...
	jp m,SHOW_EXTRA
	ld hl,TXT_NO_EXTRA	; ... or blanks
SHOW_EXTRA:
	ld de,VIDEO+1005
	call DRAW_ROW	; print one row
TIME_DOWN:
	ld a,(TIME)	; TIME - 1 (add 99 in BCD)
	add a,99h
	daa
	ld (TIME),a
	cp 99h	; Z if it went from 00 to 99: time is up
	ret

;---------------------------------------------------------------
; PRINT — copy a 0-terminated string to the screen
;
; In:        HL = string, DE = cell
; Out:       HL = byte after the 0, DE = cell after the last character
; Changes:   A, D, E, H, L; flags S Z H P/V N C
;            (on some paths only: D, E)
; Preserves: B, C (register), IX, IY
;            [static + measured: 42950 calls, 1/1 branches]
; Stack:     0 bytes max, callees included  [static]
; Cycles:    observed 90-1890 T-states (42950 calls)  [measured]
; Exit:      RET
; Called from: TITLE (4336h), TITLE (4345h), TITLE (4368h), TITLE (4371h), TITLE (437Ah), TITLE (4383h), MAIN_LOOP (4457h), MAIN_LOOP (448Ch), DRAW_CANNON (44DEh), DRAW_CANNON (44E4h), DRAW_CANNON (44EAh), DRAW_ROWS (4C00h)
; Jumped to from: PRINT (4BCBh)
;---------------------------------------------------------------
PRINT:
	ld a,(hl)	; next character
	and a
	inc hl
	ret z	; 0: done
	ld (de),a
	inc de
	jp PRINT	; go to: print the string

;---------------------------------------------------------------
; PRINT_BCD — print the last a digits of the bcd number in hl, ending at de+a-1. walks
;
; from the right: low nibble, high nibble of L, then the same of H. Rather
; than keep L and H apart it rewrites its own two loads: both start as
; LD A,L (7Dh); after two digits both become LD A,H (7Ch).
; SELF-MODIFIED: 4BDCh and 4BE5h, written here at every call.
; In:        A = number of digits (2-4), HL = BCD value, DE = cell of the
;            first (leftmost) digit
; Changes:   A, B, C (register), D, E; flags S Z H P/V N C
; Preserves: H, L, IX, IY
;            [static + measured: 452742 calls, 2/2 branches]
; Memory:    writes DIGIT_HI, DIGIT_LO
; Stack:     0 bytes max, callees included  [static]
; Cycles:    observed 182-321 T-states (452742 calls)  [measured]
; Exit:      RET
; Called from: MAIN_LOOP (4401h), SHOW_COUNTS (4B66h), SHOW_COUNTS (4B71h), SHOW_COUNTS (4B7Ch), TICK_CLOCK (4B88h)
;---------------------------------------------------------------
PRINT_BCD:
	ld c,a	; C = digits
	ld a,7Dh	; LD A,L
	ld (DIGIT_LO),a	; SELF-MODIFIES 4BDCh: start with LD A,L
	ld (DIGIT_HI),a	; SELF-MODIFIES 4BE5h
	ld b,00h
	ex de,hl	; DE = the cell after the last digit ...
	add hl,bc
	ex de,hl
DIGIT_LO:
	ld a,l	; SELF-MODIFIED: LD A,L or LD A,H
	and 0Fh	; low nibble
	add a,30h	; as a digit
	ld (de),a
	dec de	; next cell to the left
	dec c
	ret z
DIGIT_HI:
	ld a,l	; SELF-MODIFIED: LD A,L or LD A,H
	and 0F0h	; high nibble
	rrca
	rrca
	rrca
	rrca
	add a,30h
	ld (de),a
	dec de
	dec c
	ret z
	ld a,7Ch	; LD A,H
	ld (DIGIT_LO),a	; SELF-MODIFIES 4BDCh: now the high byte
	ld (DIGIT_HI),a	; SELF-MODIFIES 4BE5h
	jp DIGIT_LO

;---------------------------------------------------------------
; DRAW_ROW — print one string at de (draw_rows with b = 1)
;
; In:        HL = string, DE = cell
; Out:       HL = byte after the string's 0
; Changes:   A, B, D, E, H, L; flags S Z H P/V N C
; Preserves: C (register), IX, IY
;            [static + measured: 34356 calls, 0/0 branches]
; Stack:     4 bytes max, callees included  [static]
; Cycles:    observed 385-610 T-states (34356 calls)  [measured]
; Exit:      falls into DRAW_ROWS
; Calls:     PRINT
; Called from: DRAW_SAUCER (45ADh), DRAW_SAUCER (45DBh), UPDATE (46FAh), UPDATE (4706h), UPDATE (4939h), UPDATE (494Bh), UPDATE (4958h), UPDATE (496Ch), UPDATE (4979h), TICK_CLOCK (4BB6h)
;---------------------------------------------------------------
DRAW_ROW:
	ld b,01h	; one row

;---------------------------------------------------------------
; DRAW_ROWS — print b strings that follow each other in memory, one under the other
;
; In:        B = rows, HL = first string, DE = cell of the top row
; Out:       HL = byte after the last string's 0, DE = DE + 64*B
; Changes:   A, B, D, E, H, L; flags S Z H P/V N C
; Preserves: C (register), IX, IY
;            [static + measured: 1442 calls, 1/1 branches]
; Stack:     4 bytes max, callees included  [static]
; Cycles:    observed 729-819 T-states (1442 calls)  [measured]
; Exit:      RET
; Calls:     PRINT
; Called from: UPDATE (46BCh)
; Jumped to from: DRAW_ROWS (4C0Ch)
;---------------------------------------------------------------
DRAW_ROWS:
	push de
	call PRINT	; print it
	pop de
	push hl
	ld hl,0040h	; next row down
	add hl,de
	ex de,hl
	pop hl
	dec b
	jp nz,DRAW_ROWS	; go to: print B rows
	ret

;---------------------------------------------------------------
; DELAY — wait 4 x 80 turns of a dec/jp nz loop. called once a pass, so every speed
;
; in the game depends on it.
; In:        nothing
; Changes:   flags S Z H P/V N
; Preserves: A, B, C (register), D, E, H, L, IX, IY; flags C
;            [static + measured: 135904 calls, 2/2 branches]
; Stack:     2 bytes max, callees included  [static]
; Cycles:    4619 T-states every call (135904 calls)  [measured]
; Exit:      RET
; Called from: WAIT (43B8h), MAIN_LOOP (4432h)
;---------------------------------------------------------------
DELAY:
	push bc
	ld c,04h	; 4 x
DELAY_OUTER:
	ld b,50h	; 80 x
DELAY_INNER:
	dec b	; DEC B / JP NZ: 14 T-states a turn
	jp nz,DELAY_INNER
	dec c
	jp nz,DELAY_OUTER
	pop bc
	ret

;---------------------------------------------------------------
; GET_KEY — ask the rom for a key. the rom's routine reports a key once, when it goes
;
; down; holding it does not repeat.
; Out:       A = key code, Z set if none (contract)
; Changes:   A; flags S Z H P/V N C
; Preserves: B, C (register), D, E, H, L, IX, IY
;            [static + measured: 1574572 calls, 0/0 branches]
; Stack:     4 bytes max, callees included  [static]
; Cycles:    479 T-states every call (1574572 calls)  [measured]
; Exit:      RET
; Calls:     ROM_KBD
; Called from: TITLE (43C2h), MAIN_LOOP (4404h), MAIN_LOOP (446Fh)
;---------------------------------------------------------------
GET_KEY:
	push de	; the ROM routine uses DE
	call ROM_KBD	; Level II ROM: scan the keyboard; A = code of a key just pressed, 0 if none (uses DE)
	pop de
	and a	; Z = no key
	ret

;---------------------------------------------------------------
; RANDOM — 23 steps of a 16-bit linear-feedback shift register in seed. the new top
;
; bit is the XOR of bits 1 and 2 of the low byte, made with the parity flag:
; AND 6 leaves those two bits, and P/V is set when an even number of them
; are 1, i.e. when they are equal.
; Out:       A = high byte of the new SEED
; Changes:   A; flags S Z H P/V N C
; Preserves: B, C (register), D, E, H, L, IX, IY
;            [static + measured: 158261 calls, 2/2 branches]
; Memory:    writes SEED; reads SEED
; Stack:     4 bytes max, callees included  [static]
; Cycles:    observed 1638-1710 T-states (158261 calls)  [measured]
; Exit:      RET
; Called from: MAIN_LOOP (4411h), UPDATE (4510h), UPDATE (451Ah), UPDATE (4527h), UPDATE (4532h), UPDATE (453Ah), UPDATE (45DFh), UPDATE (4993h)
;---------------------------------------------------------------
RANDOM:
	push bc
	push hl
	ld hl,(SEED)	; the register
	ld b,17h	; 23 steps
	ld a,l
RANDOM_STEP:
	and 06h	; bits 1 and 2 of the low byte
	scf	; carry = 1 ...
	jp pe,RANDOM_SHIFT	; ... if they are equal (parity even) ...
	ccf	; ... else 0: the XOR of the two, inverted
RANDOM_SHIFT:
	ld a,h	; shift the 16 bits right, carry into bit 15
	rra
	ld h,a
	ld a,l
	rra
	and 0FEh	; bit 0 dropped
	ld l,a
	dec b
	jp nz,RANDOM_STEP
	ld (SEED),hl	; store it
	ld a,h	; A = high byte
	pop hl
	pop bc
	ret
SPARE:
	db 0FFh,00h,0FFh,00h
SEED:
	dw 00FFh
SPARE2:
	db 0FFh,00h
SAUCERS:
	db 0FFh,00h,0FFh,00h,0FFh
	db 00h,0FFh,00h,0FFh,00h
	db 0FFh,00h,0FFh,00h,0FFh
	db 00h,0FFh,00h,0FFh,00h
	db 0FFh,00h,0FFh,00h,0FFh
	db 00h,0FFh,00h,0FFh,00h
	db 0FFh,00h,0FFh,00h,0FFh
	db 00h,0FFh,00h,0FFh,00h
	db 0FFh,00h,0FFh,00h,0FFh
	db 00h,0FFh,00h,0FBh,00h
	db 0FFh,00h,0FBh,00h,0FFh
	db 00h,0FFh,00h,0FFh,00h
	db 0FFh,00h,0FFh,00h,0FBh
	db 00h,0FFh,00h,0FBh,00h
	db 0FBh,00h,0FFh,00h,0FFh
SAUCERS_END:
	db 0FFh
SHOTS:
	db 0FBh,00h,0FBh
	db 00h,0FFh,00h
	db 0FFh,00h,0FFh
	db 00h,0FFh,00h
	db 0FFh,00h,0FFh
	db 00h,0FFh,00h
	db 0FFh,00h,0FFh
	db 00h,0FFh,00h
	db 0FFh,00h,0FFh
	db 00h,0FFh,00h
	db 0FFh,00h,0FFh
	db 00h,0FFh,00h
	db 0FFh,10h,0FFh
	db 00h,0FFh,00h
	db 0FFh,00h,0FFh
	db 00h,0FFh,00h
	db 0FFh,00h,0FFh
	db 00h,0FFh,00h
	db 0FFh,00h,0FFh
	db 00h,0FFh,00h
SHOTS_END:
	db 0FFh
TXT_HITS:
	db "HITS",00h
TXT_SHOTS:
	db "SHOTS",00h
TXT_SCORE:
	db "SCORE       ",00h
TXT_TIME:
	db "TIME",00h
SCORE:
	db 00h,00h
BLINK:
	db 00h
AIM:
	db 00h
AIM_SAVE:
	db 00h
EXTRA_LEFT:
	db 00h
PACE:
	db 00h
LOADING:
	db 00h
LAUNCH_TIMER:
	db 00h
TIME:
	db 00h
	db 00h
HIT_ADJUST:
	db 00h,00h
TXT_GAME_OVER:
	db "* *  G A M E  O V E R  * *",00h
TXT_EXTRA:
	db "EXTRA TIME",00h
TXT_NO_EXTRA:
	db "          ",00h
CANNON_GFX:
	db 0A4h,20h,88h,90h,20h,20h,20h,20h,20h,20h,20h	; +_++_______
	db 00h,20h,82h,0A4h,20h,89h,90h,20h,20h,20h,20h	; |_++_++____
	db 00h,20h,20h,20h,82h,0A4h,20h,89h,90h,20h,00h	; |___++_++_|
	db 20h,20h,0A9h,20h,0A9h,20h,20h,20h,20h,20h,20h	; __+_+______
