;---------------------------------------------------------------
; LOADER — the /cmd file's own start-up, not part of the tape program. copies the
;
; ROM's 36h-byte start-up table to 4000h (on a disk system DOS has its own
; vectors there; the keyboard routine needs the ROM's), then moves the game
; from where the file loaded it (531Bh) to where it runs (42EAh), 0D23h
; bytes, and jumps to START.
; In:        nothing
; Changes:   nothing
; Preserves: A, B, C (register), D, E, H, L, IX, IY; flags S Z H P/V N C
;            [static]
; Stack:     0 bytes max, callees included  [static]
; Cycles:    not called in the scenarios
; Exit:      JP START
;---------------------------------------------------------------
LOADER:
	di	; no interrupts from here on (a disk system leaves them on)
	ld bc,0036h	; 36h bytes of the ROM start-up table
	ld hl,ROM_INIT_TABLE
	ld de,ROM_RAM	; ... to the ROM work area, as at power-on
	ldir
	nop	; a NOP left by whoever wrote the stub
	ld bc,0D23h	; 0D23h bytes: the game and the 19 bytes after it
	ld de,START	; to where the tape would have put it
	ld hl,531Bh	; from where this file puts it
	ldir
	jp START	; and start it

	end	LOADER
